from app.usecase.graph_snapshot import GraphQuery

QUERIES: dict[GraphQuery, str] = {
    "route_points": "SELECT point_id,node,snap_km FROM plexus_graph.locations WHERE point_id IN {points:Array(String)} UNION ALL SELECT oktmo AS point_id,node,snap_h*15 AS snap_km FROM plexus_casechamp.market_cities WHERE oktmo IN {points:Array(String)} AND oktmo NOT IN (SELECT point_id FROM plexus_graph.locations WHERE point_id IN {points:Array(String)})",
    "route_edges": "SELECT src,dst,way_idx,h FROM plexus_graph.edges WHERE src IN {ids:Array(Int64)} AND dst IN {ids:Array(Int64)}",
    "references_by_ids": "SELECT way_idx,way_id,name,ref,km FROM plexus_graph.ways WHERE way_idx IN {ids:Array(Int64)}",
    "road_cost_model": "SELECT value FROM plexus_atlas.atlas_metadata WHERE key='road_cost_model_version'",
    "road_costs": "SELECT way_idx,highway,surface,lanes_total,lanes_forward,lanes_backward,oneway,posted_speed_kmh,hourly_flow_pcu,flow_verified,flow_source,flow_period,hourly_flow_scope,is_ferry,source_speed_kmh,lane_data_usable FROM plexus_graph.road_costs WHERE way_id IN {ids:Array(Int64)} ORDER BY way_idx",
    "scenario_lines": "SELECT l.way_id,coalesce(nullIf(w.name,''),nullIf(w.ref,''),toString(l.way_id)),w.km,l.coordinates FROM plexus_graph.road_lines l INNER JOIN plexus_graph.ways w ON w.way_id=l.way_id WHERE l.way_id IN {ids:Array(Int64)} ORDER BY l.way_id,l.source_node,l.target_node",
    "bridge_lengths": "SELECT way_id,km FROM plexus_graph.ways WHERE is_bridge AND way_id IN {ids:Array(Int64)}",
    "bridge_parts": "SELECT l.way_id,w.name,w.ref,w.highway,w.km,l.source_node,l.target_node,l.coordinates FROM plexus_graph.road_lines l INNER JOIN plexus_graph.ways w ON w.way_id=l.way_id WHERE w.is_bridge AND l.way_id IN (SELECT way_id FROM plexus_graph.road_lines WHERE min_lon<={east:Float64} AND max_lon>={west:Float64} AND min_lat<={north:Float64} AND max_lat>={south:Float64}) ORDER BY l.way_id,l.source_node,l.target_node LIMIT 2001",
    "locations": "SELECT point_id,settlement,region,node,lon,lat,snap_km FROM plexus_graph.locations WHERE lowerUTF8(ifNull(settlement,'')) LIKE {pattern:String} AND ({region:String}='' OR region={region:String}) ORDER BY population DESC NULLS LAST LIMIT 20",
    "region_name": "SELECT region FROM plexus_graph.region_codes WHERE oktmo={region_id:String}",
    "ways": "SELECT way_idx,way_id,name,ref,highway,speed_kmh FROM plexus_graph.ways WHERE way_idx IN {ids:Array(Int64)}",
    "way_indices": "SELECT way_id,way_idx FROM plexus_graph.ways WHERE way_id IN {ids:Array(Int64)}",
    "points": "SELECT point_id,node,snap_km FROM plexus_graph.points",
    "origins": "SELECT point_id,population FROM plexus_casechamp.idx_np WHERE season={season:String} AND region={region:String} ORDER BY point_id",
    "cities": "SELECT city,node,snap_h,population,oktmo FROM plexus_casechamp.market_cities ORDER BY city",
    "trunk": "SELECT city_from,city_to,transport_type,distance_hr FROM plexus_casechamp.stg_intercity WHERE transport_type IN ('rail','air') AND distance_hr IS NOT NULL",
    "manual": "SELECT from_id,to_id,h,mode FROM plexus_casechamp.manual_links_ru WHERE season={season:String}",
    "manual_named": "SELECT m.from_id,f.settlement,m.to_id,t.settlement,m.mode,m.h,coalesce(f.region,t.region) FROM plexus_casechamp.manual_links_ru m LEFT JOIN plexus_graph.locations f ON f.point_id=m.from_id LEFT JOIN plexus_graph.locations t ON t.point_id=m.to_id WHERE m.season={season:String} ORDER BY m.from_id,m.to_id,m.mode",
    "normalization": "SELECT avg(share) FROM (SELECT hansen_2h/hansen_idx*100 AS share FROM plexus_casechamp.idx_np WHERE season='road' AND hansen_idx>0 ORDER BY point_id)",
    "expected": "SELECT hansen_idx FROM plexus_casechamp.idx_region WHERE region={region:String} AND season={season:String}",
    "delta_points": "SELECT point_id,population,node,snap_km/15 FROM plexus_graph.region_points WHERE season='road' AND region={region:String} ORDER BY point_id",
    "delta_cities": "SELECT city,oktmo,node,snap_h,population FROM plexus_casechamp.market_cities ORDER BY city",
    "delta_times": "SELECT point_id,city,road_h FROM plexus_casechamp.np_city_times WHERE season='road' AND point_id IN (SELECT point_id FROM plexus_casechamp.idx_np WHERE season='road' AND region={region:String})",
    "city_times": "SELECT point_id,city,road_h FROM plexus_casechamp.np_city_times WHERE season='road' AND point_id IN (SELECT oktmo FROM plexus_casechamp.market_cities)",
    "terminal_nodes": "SELECT DISTINCT node FROM (SELECT node FROM plexus_graph.points WHERE node>=0 UNION ALL SELECT node FROM plexus_casechamp.market_cities) ORDER BY node",
    "references": "SELECT way_idx,way_id,name,ref,km FROM plexus_graph.ways WHERE hasAny(arrayMap(x -> trimBoth(x), splitByChar(';', ifNull(ref,''))), {references:Array(String)})",
    "local_road_ways": "SELECT way_idx,way_id,name,km FROM plexus_graph.ways WHERE replaceAll(lowerUTF8(ifNull(name,'')),'ё','е')={street:String} AND way_id IN (SELECT way_id FROM plexus_graph.road_lines WHERE min_lon<={east:Float64} AND max_lon>={west:Float64} AND min_lat<={north:Float64} AND max_lat>={south:Float64}) ORDER BY way_id",
    "road_reference": "SELECT DISTINCT ref FROM plexus_graph.road_lookup WHERE lookup IN {names:Array(String)}",
    "market_places": "SELECT DISTINCT oktmo_from,city_from,region_from,lon_from,lat_from FROM plexus_casechamp.stg_intercity WHERE replaceAll(lowerUTF8(ifNull(city_from,'')),'ё','е') LIKE {pattern:String}",
    "place_names": "SELECT point_id,settlement,region FROM plexus_graph.locations WHERE point_id IN {ids:Array(String)} ORDER BY point_id",
    "region_list": "SELECT DISTINCT region FROM plexus_graph.locations WHERE region IS NOT NULL ORDER BY region",
    "settlement_regions": "SELECT region,lon,lat FROM plexus_graph.locations WHERE lon IS NOT NULL AND lat IS NOT NULL AND region IS NOT NULL",
    "corridor_places": "SELECT point_id,settlement,region,lon,lat FROM plexus_graph.locations WHERE replaceAll(lowerUTF8(ifNull(settlement,'')),'ё','е') LIKE {pattern:String}",
    "corridor_edges": "SELECT src,dst,way_idx FROM plexus_graph.edges WHERE way_idx IN {ids:Array(Int64)}",
    "corridor_nodes": "SELECT node,lon,lat FROM plexus_graph.nodes WHERE node IN {ids:Array(Int64)} ORDER BY node",
    "region_codes": "SELECT oktmo,region FROM plexus_graph.region_codes WHERE region IN {regions:Array(String)}",
    "candidates": "SELECT way_idx,way_id,coalesce(nullIf(name,''),nullIf(ref,''),toString(way_id)),km FROM plexus_graph.ways WHERE way_idx IN {ids:Array(Int64)} AND NOT coalesce(is_ferry,false)",
    "impact_places": "SELECT point_id,settlement,lon,lat FROM plexus_graph.locations WHERE region={region:String}",
    "regions": "SELECT region FROM plexus_casechamp.idx_region WHERE season='road' ORDER BY region",
    "model_version": "SELECT value FROM plexus_atlas.atlas_metadata WHERE key='model_version'",
    "manual_v2": "SELECT from_id,to_id,h,mode FROM plexus_casechamp.manual_links_ru WHERE season={season:String} AND ({road_only:UInt8}=0 OR mode IN ('winter_road','ice_crossing','pontoon_bridge')) AND ({season:String}!='summer' OR mode NOT IN ('winter_road','ice_crossing'))",
}
ARRAYS = {
    "edges": "SELECT src,dst,h,km,way_idx FROM plexus_graph.edges ORDER BY way_idx,src,dst",
    "nodes": "SELECT node,lat,lon FROM plexus_graph.nodes ORDER BY node",
    "ranks": "SELECT multiIf(replaceAll(highway,'_link','')='motorway',0,replaceAll(highway,'_link','')='trunk',1,replaceAll(highway,'_link','')='primary',2,replaceAll(highway,'_link','')='secondary',3,replaceAll(highway,'_link','')='tertiary',4,5) AS rank FROM plexus_graph.ways ORDER BY way_idx",
    "seasons": "SELECT toUInt8(multiIf(operating_season='all',0,operating_season='summer',1,operating_season='winter',2,3)) AS season FROM plexus_graph.ways ORDER BY way_idx",
}
